  /** The sentence in [lang] (English when missing), with {placeholders} filled in. */
  fun t(key: String, lang: String, vars: Map<String, String> = emptyMap()): String {
    var s = all[lang]?.get(key) ?: all["en"]?.get(key) ?: key
    for ((k, v) in vars) s = s.replace("{" + k + "}", v)
    return s
  }
